'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Geral','Ponto Vermelho','Mira 2x','Mira 4x','AWM','Olhadinha'];
const keys=['geral','red','x2','x4','awm','look'];
const themes=[['purple','Hype Roxo','#ad68d8','#e2baff','#0d0713','#1b1125','#251630','#4b315d'],['obsidian','Obsidian','#a5a5b5','#e4e4e9','#0b0b0e','#1a1a21','#252530','#474750'],['frost','Frost','#5c9ce7','#c2e1ff','#091521','#14263b','#1b354f','#315676'],['crimson','Crimson','#d15379','#ffc6d6','#190b13','#2a1723','#371d2a','#734357'],['emerald','Emerald','#42b98d','#b7f3dc','#081913','#152b23','#1d3b30','#33634e'],['gold','Gold','#c39b56','#ffe0a0','#171209','#2c2417','#393022','#705c39']];
const icons={house:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/><path d="M12 1v4m0 14v4M1 12h4m14 0h4"/>',layout:'<rect x="2" y="3" width="20" height="18" rx="2"/><path d="M2 9h20M9 9v12"/>',star:'<path d="m12 2 3 6.3 7 .9-5 5 .9 7-5.9-3.1-5.9 3.1.9-7-5-5 7-.9z"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',activity:'<path d="M2 12h4l3-8 6 16 3-8h4"/>',bookmark:'<path d="M5 3h14v18l-7-5-7 5z"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="7" cy="12" r="1"/><circle cx="12" cy="7" r="1"/><circle cx="17" cy="11" r="1"/><path d="M14 21a3 3 0 0 1-2-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a2 2 0 0 0 .4 2l-2.2 2.2a2 2 0 0 0-2-.4L14 21h-4l-.7-2.2a2 2 0 0 0-2 .4L5 17a2 2 0 0 0 .4-2L3 14v-4l2.4-1a2 2 0 0 0-.4-2L7.2 5a2 2 0 0 0 2 .4L10 3h4l.7 2.4a2 2 0 0 0 2-.4L19 7.2a2 2 0 0 0-.4 2L21 10v4z"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9.5 9a3 3 0 1 1 4 3c-1.5.7-1.5 1.3-1.5 2.5M12 18h.01"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',file:'<path d="M6 2h9l5 5v15H6z"/><path d="M15 2v6h5M9 13h8M9 17h8"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',monitor:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8M12 18v4"/>',check:'<path d="m4 12 5 5L20 6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6"/>',edit:'<path d="m3 17 12-12 4 4L7 21H3zm11-11 4 4"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',save:'<path d="M4 3h14l3 3v15H3V3zm3 0v7h10V3M7 21v-8h10v8"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 17v4h18v-4"/>',thermo:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0z"/><path d="M12 10v9"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 9h6v6H9zM3 9h3m-3 6h3m12-6h3m-3 6h3M9 3v3m6-3v3m-6 12v3m6-3v3"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7v.5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
const ic=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const menu=[['GERAL',[['home','Início','house'],['dashboard','Painel principal','dashboard']]],['FERRAMENTAS',[['sensi','Sensi IA','target'],['hud','HUD Studio','layout'],['famous','Sensi e HUDs Famosos','star'],['calibration','Hype Adapt','sliders'],['optimize','Diagnóstico do PC','activity'],['saved','Minhas Sensis / HUDs','bookmark']]],['APLICATIVO',[['themes','Temas e logos','palette'],['settings','Configurações','settings'],['faq','Perguntas frequentes','help'],['terms','Termos de Uso','file'],['privacy','Privacidade','shield']]]];
const defaults={theme:'purple',animations:true,tutorialDone:false,sensis:[],huds:[],favPlayers:[],game:'Free Fire',quiz:{},lastGenerated:null};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('hype-desktop-v1')||'{}')}}catch{state={...defaults}};
let page='home',quizStep=0,quizAnswers={},generated=null,editorHud=null,editorSelected='',editorUndo=[],editorRedo=[],favFilter=false,famousSearch='',famousRegion='all',famousSelected=null,calibrationKey='geral',hudFilter='all';
function persist(){try{localStorage.setItem('hype-desktop-v1',JSON.stringify(state))}catch{toast('Não foi possível salvar os dados locais')}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
function applyTheme(){let t=themes.find(x=>x[0]===state.theme)||themes[0];const css={'--accent':t[2],'--accent2':t[3],'--bg':t[4],'--panel':t[5],'--surface':t[6],'--border':t[7],'--field':t[4]};for(let [k,v]of Object.entries(css))document.documentElement.style.setProperty(k,v);document.documentElement.style.setProperty('--shadow',t[2]+'30');$('#brandLogo').src='assets/images/logos/logo-'+t[0]+'.png';$('#splashLogo').src='assets/images/logos/logo-'+t[0]+'.png'}
function navRender(){let html='';for(const [heading,items] of menu){html+=`<div class="group-label">${heading}</div>`;for(const [id,name,icon] of items){html+=`<button class="navbtn ${page===id?'active':''}" data-nav="${id}"><span class="navicon">${ic(icon,19)}</span>${name}</button>`}}$('#nav').innerHTML=html}
function navigate(p){page=p;navRender();$('#breadcrumb').innerHTML=`Hype Sensi <span>/ ${escapeHTML(menu.flatMap(x=>x[1]).find(x=>x[0]===p)?.[1]||'Desktop')}</span>`;$('#content').innerHTML=pages[p]?pages[p]():pageDashboard();$('#content').scrollTop=0;wire();}
const header=(label,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;
const stat=(value,label,icon)=>`<div class="card"><div class="row">${ic(icon,21)}<div><span class="statnum">${value}</span><span class="statlabel">${label}</span></div></div></div>`;
const toolCards=()=>[['sensi','target','Sensi IA','Questionário adaptativo e geração de valores 0 a 200.'],['hud','layout','HUD Studio','Arraste, redimensione e salve seus controles.'],['famous','star','Famosos','Biblioteca mundial com fontes e códigos publicados.'],['calibration','sliders','Hype Adapt','Calibração gradual depois dos seus testes.'],['optimize','activity','Diagnóstico','Informações reais do Windows e estado térmico.'],['saved','bookmark','Meus Perfis','Seus HUDs e sensibilidades, guardados localmente.'],['themes','palette','Temas','Seis logos e seis identidades visuais.'],['faq','help','Ajuda','Como configurar, importar e proteger seus dados.']].map(([id,icon,name,desc])=>`<button class="card toolcard" data-nav="${id}"><span class="toolicon">${ic(icon,24)}</span><h3>${name}</h3><p>${desc}</p><div class="eyebrow">ABRIR ${ic('arrow',12)}</div></button>`).join('');
function pageHome(){return `<div class="hero bg-welcome"><div><div class="eyebrow">HYPE SENSI • WEBAPP EDITION</div><h1>Seu controle.<br>Sua precisão.</h1><p>O seu espaço para criar sensibilidades, configurar HUDs e organizar o que funciona para você no Free Fire.</p><div class="action-row"><button data-nav="dashboard" class="primary">Vamos ao Menu ${ic('arrow',16)}</button><button data-nav="sensi" class="secondary">Gerar sensibilidade</button></div></div><img src="assets/images/logos/logo-${state.theme}.png" alt="Logo HypeSensi"></div><div class="section-title">Acesso rápido</div><div class="grid four">${toolCards()}</div><div class="section-title">Sobre este aplicativo</div><div class="notice">Hype Sensi é uma ferramenta independente para planejamento de controles. Não altera a memória, os arquivos nem as configurações do Free Fire. Aplicação dos valores e códigos no jogo é feita pelo próprio usuário.</div>`}
function pageDashboard(){return `${header('CENTRAL DE FERRAMENTAS','Escolha por onde começar','Todas as ferramentas da versão Desktop em um único painel.')}<div class="grid four">${toolCards()}</div><div class="section-title">Seus dados</div><div class="grid">${stat(state.sensis.length,'Sensibilidades salvas','target')}${stat(state.huds.length,'HUDs personalizados','layout')}${stat(state.favPlayers.length,'Famosos favoritos','heart')}</div>`}
const questions=[{id:'emulator',title:'Qual emulador você utiliza?',options:['BlueStacks','MSI App Player','LDPlayer','GameLoop','MuMu Player','Outro emulador']},{id:'game',title:'Qual versão você joga?',options:['Free Fire','Free Fire MAX']},{id:'ram',title:'Quanto de RAM seu PC possui?',options:['Até 4 GB','8 GB','12 a 16 GB','24 a 32 GB','Mais de 32 GB','Não sei']},{id:'fps',title:'Como está a fluidez do jogo?',options:['Estável e fluido','Pequenas quedas','Quedas frequentes','Não sei']},{id:'dpi',title:'Qual é o DPI configurado no seu mouse?',options:['400','800','1200','1600','2400+','Não sei']},{id:'mouse',title:'Como você costuma mover o mouse?',options:['Movimentos curtos','Movimentos médios','Movimentos longos']},{id:'aim',title:'Qual dificuldade você quer corrigir?',options:['Passa do alvo','Fica abaixo do alvo','Mira tremendo','Movimento muito lento','Quero equilibrar']},{id:'speed',title:'Prefere sensibilidade...',options:['Mais controlada','Equilibrada','Mais rápida']},{id:'scope',title:'Qual mira você mais utiliza?',options:['Sem mira / Geral','Ponto vermelho','Mira 2x','Mira 4x','AWM']},{id:'adjust',title:'Qual intensidade de ajuste inicial?',options:['Conservador','Moderado','Mais perceptível']}];
function pageSensi(){if(generated)return renderGenerated();const q=questions[quizStep];return `${header('CONFIGURAÇÃO INTELIGENTE','Sensi IA','Questionário para Windows e emulador, sem perguntas de celular.') }<div class="quiz"><div class="row space"><span class="eyebrow">PERGUNTA ${quizStep+1} DE ${questions.length}</span><span class="muted">${Math.round(quizStep/questions.length*100)}%</span></div><div class="progress"><div style="width:${quizStep/questions.length*100}%"></div></div><div class="card"><h2>${q.title}</h2><p>Escolha a opção que mais combina com seu uso.</p><div class="choice-grid">${q.options.map(o=>`<button class="choice ${quizAnswers[q.id]===o?'selected':''}" data-answer="${escapeHTML(o)}">${escapeHTML(o)}</button>`).join('')}</div><div class="action-row"><button class="secondary" data-action="quizPrev" ${quizStep===0?'disabled':''}>Voltar</button><button class="primary" data-action="quizNext" ${!quizAnswers[q.id]?'disabled':''}>${quizStep===questions.length-1?'Gerar Sensi':'Continuar'} ${ic('arrow',15)}</button></div></div><p class="muted" style="font-size:12px">Recomendações iniciais calculadas por regras transparentes e refinadas por calibração; não prometem precisão automática ou resultados em partidas.</p></div>`}
const clamp=(x,min,max)=>Math.min(max,Math.max(min,x));
function generator(a){let base=160,red=168,x2=151,x4=137,awm=88,look=130;let speed=a.speed||'';let speedDelta=speed==='Mais rápida'?14:speed==='Mais controlada'?-13:0;let issue=a.aim||'';let adjust=issue==='Passa do alvo'?-13:issue==='Movimento muito lento'?12:issue==='Mira tremendo'?-10:issue==='Fica abaixo do alvo'?8:0;let dpi=a.dpi||'';let dpiDelta=(dpi==='1600'||dpi==='2400+')?-8:dpi==='400'?6:0;let motion=a.mouse==='Movimentos curtos'?5:a.mouse==='Movimentos longos'?-6:0;let performance=a.fps==='Quedas frequentes'?-8:a.fps==='Pequenas quedas'?-4:0;let intensity=a.adjust==='Conservador'?.55:a.adjust==='Mais perceptível'?1.2:1;let delta=Math.round((speedDelta+adjust+dpiDelta+motion+performance)*intensity);let v=[base,red,x2,x4,awm,look].map((n,i)=>clamp(n+Math.round(delta*[1,1,0.8,0.6,0.45,.65][i]),0,200));if(a.scope==='Ponto vermelho')v[1]=clamp(v[1]+4,0,200);if(a.scope==='Mira 2x')v[2]=clamp(v[2]+4,0,200);if(a.scope==='Mira 4x')v[3]=clamp(v[3]+4,0,200);if(a.scope==='AWM')v[4]=clamp(v[4]+4,0,200);return Object.fromEntries(keys.map((k,i)=>[k,v[i]]))}
function sensiRows(v,editable=false){return keys.map((k,i)=>`<div class="resultline"><div class="rangehead"><span>${names[i]}</span><strong id="sv-${k}">${v[k]}</strong></div>${editable?`<input type="range" min="0" max="200" step="1" value="${v[k]}" data-sensirange="${k}" aria-label="${names[i]}">`:`<div class="bar"><div style="width:${(v[k]/2)}%"></div></div>`}</div>`).join('')}
function renderGenerated(){return `${header('CONFIGURAÇÃO GERADA','Sua sensibilidade inicial','Ajuste os valores e salve um perfil para testar dentro do jogo.','<button data-action="resetQuiz" class="secondary">Refazer quiz</button>')}<div class="grid two"><div class="card"><div class="row space"><b>HYPE ADAPT • EMULADOR</b><span class="chip">0–200</span></div>${sensiRows(generated,true)}<div class="action-row"><button class="primary" data-action="saveGenerated">${ic('save',15)} Salvar perfil</button><button class="secondary" data-action="copyGenerated">${ic('copy',15)} Copiar valores</button></div></div><div class="card"><h3>Como testar</h3><p>1. Aplique os valores no menu de sensibilidade do jogo.</p><p>2. Treine alguns movimentos em um ambiente de prática.</p><p>3. Observe se o movimento passa ou fica aquém do alvo.</p><p>4. Use a Calibração para corrigir aos poucos.</p><div class="separator"></div><h3>Respostas consideradas</h3>${Object.entries(quizAnswers).map(([k,v])=>`<div class="kv"><span>${escapeHTML(questions.find(x=>x.id===k)?.title||k)}</span><b>${escapeHTML(v)}</b></div>`).join('')}<div class="notice">Esta é uma recomendação inicial orientativa, não uma configuração oficial ou comprovada para um dispositivo específico.</div></div></div>`}
function renderCalibration(){let items=state.sensis;let current=items.find(x=>x.id===selectedSensiId)||items[0];let val=current?current.values[calibrationKey]:generated?.[calibrationKey]??160;return `${header('HYPE ADAPT','Calibração gradual','Escolha uma sensibilidade salva e ajuste o valor que apresentou dificuldade.')}<div class="grid two"><div class="card"><label class="formlabel">Perfil</label><select class="field" id="calProfile">${items.length?items.map(x=>`<option value="${x.id}" ${x.id===current?.id?'selected':''}>${escapeHTML(x.name)}</option>`).join(''):'<option value="">Nenhum perfil salvo</option>'}</select><label class="formlabel" style="margin-top:17px">Controle</label><select class="field" id="calKey">${keys.map((k,i)=>`<option value="${k}" ${calibrationKey===k?'selected':''}>${names[i]}</option>`).join('')}</select><div class="section-title">Valor atual: <span id="calValue">${val}</span></div><input type="range" min="0" max="200" value="${val}" id="calRange"><div class="action-row"><button class="secondary" data-caldelta="-5">-5</button><button class="secondary" data-caldelta="-2">-2</button><button class="secondary" data-caldelta="2">+2</button><button class="secondary" data-caldelta="5">+5</button></div><div style="margin-top:14px"><button class="primary" data-action="calSave" ${!current?'disabled':''}>Salvar ajuste</button></div></div><div class="card"><h3>Como decidir</h3><p>Se estiver ultrapassando o ponto desejado, teste uma pequena redução. Se o movimento estiver curto, experimente aumentar um pouco.</p><p>Faça uma mudança por vez e compare antes de continuar.</p><div class="notice">O calibrador não acessa o Free Fire. Ele auxilia ajustes manuais e salva os resultados dentro da Hype Sensi.</div></div></div>`}
let selectedSensiId='';
const controlList=[['move','Movimento / Joystick','◎',13,77,18,'circle'],['shoot','Disparo principal','+',83,70,14,'circle'],['shootleft','Disparo esquerdo','+',22,26,11,'circle'],['aim','Mira / ADS','⌖',76,39,11,'circle'],['jump','Pular','↑',91,45,10,'circle'],['crouch','Agachar','↓',87,57,10,'circle'],['prone','Deitar','—',95,61,9,'rect'],['run','Correr','⇧',31,73,10,'circle'],['reload','Recarregar','↻',65,56,10,'circle'],['gloo','Parede de gel','▧',71,80,11,'circle'],['grenade','Granada','○',60,76,9,'circle'],['heal','Kit médico','+',49,82,9,'rect'],['skill','Habilidade','◇',56,37,10,'circle'],['bag','Mochila','▣',96,25,9,'rect'],['weapon','Troca arma','Ⅰ/Ⅱ',83,15,11,'rect'],['interact','Interagir','↗',50,54,10,'circle'],['emote','Emotes','☺',41,26,8,'circle'],['map','Mini-mapa','MAP',13,20,15,'rect']];
const makeHud=(fingers=4)=>({id:uid(),name:`HUD ${fingers} dedos`,fingers,created:new Date().toISOString(),controls:controlList.map(([id,label,symbol,x,y,size,shape])=>({id,label,symbol,x,y,size,shape,opacity:80,visible:true}))});
function uid(){return 'h'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function renderHUD(){return `${header('EDITOR VISUAL','HUD Studio','Editor independente de posições, tamanhos e transparência dos controles.','<button class="secondary" data-nav="saved">Meus HUDs</button>')}<div class="grid two"><div class="card"><span class="toolicon">${ic('plus',23)}</span><h3>Criar layout</h3><p>Comece com um modelo de 2, 3, 4, 5 ou 6 dedos. Arraste os controles e ajuste como quiser.</p><div class="pill-select">${[2,3,4,5,6].map(n=>`<button data-createhud="${n}">${n} dedos</button>`).join('')}</div></div><div class="card"><span class="toolicon">${ic('layout',23)}</span><h3>Seus HUDs</h3><p>Você tem ${state.huds.length} layout(s) salvos. Edite uma cópia ou continue de onde parou.</p><button data-nav="saved" class="secondary">Abrir biblioteca pessoal</button></div></div><div class="section-title">O que pode ser ajustado</div><div class="grid">${[['move','Posição livre','Arraste cada controle na prévia horizontal.'],['sliders','Tamanho e opacidade','Regule o tamanho e a transparência de forma independente.'],['save','Salvamento local','Salve seus layouts e exporte backups.']].map(x=>`<div class="card"><div class="toolicon">${ic(x[0])}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><div class="notice" style="margin-top:14px">Os rótulos e símbolos são representações próprias da Hype Sensi, não cópias dos arquivos gráficos do jogo. As opções variam conforme a versão do Free Fire; os perfis exportados pela Hype Sensi não são códigos oficiais importáveis.</div>`}
function editorScene(hud){return `<div class="hud-canvas-wrap"><div class="hud-canvas" id="hudCanvas">${hud.controls.filter(x=>x.visible).map(c=>`<div class="hud-control ${c.shape==='rect'?'rect':''} ${c.id===editorSelected?'selected':''}" data-control="${c.id}" style="left:${c.x}%;top:${c.y}%;width:${c.size}%;aspect-ratio:1;opacity:${c.opacity/100}"><span>${escapeHTML(c.symbol)}</span></div>`).join('')}</div></div>`}
function editorPanel(){let c=editorHud.controls.find(x=>x.id===editorSelected)||editorHud.controls[0];return `<div class="card"><h3>Controle selecionado</h3><select class="field" id="controlSelect">${editorHud.controls.map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${escapeHTML(x.label)}</option>`).join('')}</select><div style="margin-top:14px"><label class="formlabel">Tamanho <b id="hudSizeLabel">${c.size}%</b></label><input id="hudSize" type="range" min="5" max="25" step="1" value="${c.size}"><label class="formlabel">Transparência <b id="hudOpacityLabel">${c.opacity}%</b></label><input id="hudOpacity" type="range" min="1" max="100" step="1" value="${c.opacity}"><label class="formlabel">Posição X (%)</label><input class="field" id="hudX" type="number" min="0" max="100" step="0.1" value="${c.x}"><label class="formlabel">Posição Y (%)</label><input class="field" id="hudY" type="number" min="0" max="100" step="0.1" value="${c.y}"></div><div class="separator"></div><label class="row"><input type="checkbox" id="hudVisible" ${c.visible?'checked':''}> Exibir controle</label></div><div class="card"><h3>Controles</h3><div class="hud-list">${editorHud.controls.map(x=>`<button class="hud-item ${x.id===editorSelected?'active':''}" data-selecthud="${x.id}"><span>${escapeHTML(x.label)}</span><span>${x.visible?'◉':'○'}</span></button>`).join('')}</div></div>`}
function pageHudEditor(){if(!editorHud){editorHud=makeHud(4);editorSelected=editorHud.controls[0].id}return `${header('HUD STUDIO','Editor personalizado','Arraste os controles na área horizontal ou informe as coordenadas.')}<div class="row wrap" style="margin-bottom:14px"><input class="field" id="hudName" style="max-width:260px" value="${escapeHTML(editorHud.name)}" aria-label="Nome do HUD"><button class="primary" data-action="saveHud">${ic('save',15)} Salvar HUD</button><button class="secondary" data-action="undoHud">Desfazer</button><button class="secondary" data-action="redoHud">Refazer</button><button class="ghost" data-action="resetHud">Restaurar padrão</button></div><div class="editor-layout"><div><div class="card">${editorScene(editorHud)}<div class="row space wrap" style="margin-top:12px"><span class="chip">${editorHud.fingers} dedos • Proporção 16:9</span><span class="muted" style="font-size:12px">Arraste usando mouse ou toque.</span></div></div><div class="notice" style="margin-top:12px">Layouts são prévias visuais independentes. A Hype Sensi não importa automaticamente HUDs no Free Fire.</div></div><div class="editor-aside">${editorPanel()}</div></div>`}
function saveHud(){if(!editorHud)return;editorHud.name=($('#hudName')?.value||editorHud.name).trim()||'Meu HUD';if(!editorHud.id)editorHud.id=uid();let i=state.huds.findIndex(x=>x.id===editorHud.id);if(i<0)state.huds.push(structuredClone(editorHud));else state.huds[i]=structuredClone(editorHud);persist();toast('HUD salvo em Meus Perfis')}
function editorCheckpoint(){editorUndo.push(JSON.stringify(editorHud.controls));if(editorUndo.length>40)editorUndo.shift();editorRedo=[]}
function editorChange(id,prop,value){let c=editorHud?.controls.find(x=>x.id===id);if(!c)return;editorCheckpoint();c[prop]=value;if(prop==='visible'){navigate('hudEditor')}else updateHudLive()}
function updateHudLive(){if(!editorHud)return;const c=editorHud.controls.find(x=>x.id===editorSelected);if(!c)return;const el=$(`[data-control="${c.id}"]`);if(el){el.style.left=c.x+'%';el.style.top=c.y+'%';el.style.width=c.size+'%';el.style.opacity=c.opacity/100;}if($('#hudSizeLabel'))$('#hudSizeLabel').textContent=c.size+'%';if($('#hudOpacityLabel'))$('#hudOpacityLabel').textContent=c.opacity+'%';if($('#hudX'))$('#hudX').value=c.x;if($('#hudY'))$('#hudY').value=c.y}
function pageSaved(){return `${header('BIBLIOTECA LOCAL','Meus Perfis','Sensibilidades e HUDs ficam salvos apenas neste computador.','<button class="secondary" data-action="exportBackup">Exportar backup</button>')}<div class="section-title">Sensibilidades (${state.sensis.length})</div>${state.sensis.length?state.sensis.map(x=>`<div class="listrow"><div><b>${escapeHTML(x.name)}</b><small>${escapeHTML(x.platform||'Emulador')} • ${new Date(x.created).toLocaleDateString('pt-BR')}</small></div><div class="action-row"><button class="secondary small" data-open-sensi="${x.id}">Abrir</button><button class="secondary small" data-duplicate-sensi="${x.id}">Duplicar</button><button class="danger small" data-delete-sensi="${x.id}">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhuma sensibilidade salva. Use Sensi IA para gerar uma.</div>'}<div class="section-title">HUDs (${state.huds.length})</div>${state.huds.length?state.huds.map(x=>`<div class="listrow"><div><b>${escapeHTML(x.name)}</b><small>${x.fingers} dedos • ${new Date(x.created).toLocaleDateString('pt-BR')}</small></div><div class="action-row"><button class="secondary small" data-open-hud="${x.id}">Editar</button><button class="secondary small" data-duplicate-hud="${x.id}">Duplicar</button><button class="danger small" data-delete-hud="${x.id}">Excluir</button></div></div>`).join(''):'<div class="empty">Nenhum HUD salvo. Abra HUD Studio para criar um.</div>'}`}
