function famousItem(p){let [name,region,role,platform,status]=p;return `<div class="listrow"><div><b>${escapeHTML(name)}</b><small>${escapeHTML(region)} • ${escapeHTML(role)} • ${escapeHTML(platform)} </small><span class="chip">${status==='published'?'Publicado por terceiro':'Aguardando fonte de HUD / Sensi'}</span></div><div class="action-row"><button class="secondary small" data-famous="${escapeHTML(name)}">Abrir perfil</button><button class="secondary small" data-fav="${escapeHTML(name)}">${state.favPlayers.includes(name)?'♥ Favorito':'Favoritar'}</button></div></div>`}
function pageFamous(){if(famousSelected)return famousDetail();let arr=famous.filter(p=>(famousRegion==='all'||p[1]===famousRegion)&&(!favFilter||state.favPlayers.includes(p[0]))&&p[0].toLowerCase().includes(famousSearch.toLowerCase()));return `${header('BIBLIOTECA DE JOGADORES','Sensi e HUDs dos Famosos',`${famous.length} perfis de referência • só mostramos valores e códigos com fonte identificada.`)}<div class="card"><div class="row wrap"><input class="field" id="famousSearch" style="flex:2;min-width:200px" placeholder="Pesquisar jogador..." value="${escapeHTML(famousSearch)}"><select class="field" id="famousRegion" style="flex:1;min-width:150px"><option value="all" ${famousRegion==='all'?'selected':''}>Todas as regiões</option><option value="Brasil" ${famousRegion==='Brasil'?'selected':''}>Brasil</option><option value="Internacional" ${famousRegion==='Internacional'?'selected':''}>Internacional</option></select><label class="row"><input type="checkbox" id="famousFavorites" ${favFilter?'checked':''}> Favoritos</label></div></div><div class="notice" style="margin:12px 0">Os perfis não garantem uma configuração publicada. Fotos de HUD, sensis e códigos só serão exibidos quando a origem puder ser identificada; códigos podem expirar ou mudar após atualizações.</div><div id="famousList"><div class="row space" style="margin:17px 0"><b>${arr.length} resultado(s)</b><span class="muted">Brasil e internacional</span></div>${arr.map(famousItem).join('')||'<div class="empty">Nenhum jogador corresponde aos filtros.</div>'}</div>`}
function famousDetail(){let p=famous.find(x=>x[0]===famousSelected);if(!p){famousSelected=null;return pageFamous()}let published=p[4]==='published';return `<button class="secondary sideback" data-action="famousBack">${ic('back',15)} Voltar à biblioteca</button>${header('PERFIL PÚBLICO',escapeHTML(p[0]),`${escapeHTML(p[1])} • ${escapeHTML(p[2])} • ${escapeHTML(p[3])}`)}<div class="grid two"><div class="card"><h3>Sensibilidade</h3>${published?sensiRows(freitas.values):'<div class="empty">Sem valores pessoais confirmados para mostrar.</div>'}<div style="margin-top:13px" class="notice">${published?'Valores reportados por fonte terceirizada, não medidos pela Hype Sensi.':'Nenhuma sensibilidade é inventada para preencher o perfil.'}</div>${published?`<button class="secondary" style="margin-top:12px" data-action="copyFreitas">${ic('copy',14)} Copiar sensibilidade publicada</button>`:''}</div><div class="card"><h3>HUD do jogador</h3>${published?`<div class="notice">Código divulgado em ${freitas.date}. Compatibilidade atual não verificada.</div><label class="formlabel" style="margin-top:13px">Código publicado</label><input class="field" readonly value="${freitas.code}"><button data-action="copyFreitasCode" class="secondary" style="margin-top:12px">${ic('copy',14)} Copiar código</button><p><a class="muted-link" href="${freitas.source}" target="_blank" rel="noopener noreferrer">Consultar fonte original ↗</a></p>`:'<div class="empty">Imagem ou código do HUD não disponíveis com fonte suficiente.</div>'}<div class="separator"></div><button class="secondary" data-fav="${escapeHTML(p[0])}">${state.favPlayers.includes(p[0])?'Retirar dos favoritos':'Adicionar aos favoritos'}</button><p class="muted">O HUD Studio permite criar um modelo próprio, mas não transforma um layout em código oficial.</p><button class="primary" data-nav="hud">Abrir HUD Studio</button></div></div>`}
function pageOptimize(){return `${header('DIAGNÓSTICO LOCAL','Desempenho do computador','Consulta opcional de processador, memória, sistema e sensores acessíveis.')}<div class="row wrap" style="margin-bottom:18px"><button class="primary" data-action="diagnose">${ic('activity',16)} Iniciar diagnóstico</button><span class="muted">Sem elevação de privilégios ou monitoramento em segundo plano.</span></div><div id="diagnostic" class="grid">${stat('—','Processador','cpu')}${stat('—','RAM total','dashboard')}${stat('—','Carga térmica','thermo')}</div><div class="section-title">O que significa a leitura?</div><div class="notice">Se o Windows oferecer um sensor ACPI, a leitura será identificada como do sensor ACPI (e não necessariamente da CPU). Quando o sensor não estiver disponível, exibiremos apenas uma classificação orientativa baseada na carga do processador, sem inventar graus Celsius. Não medimos FPS do Free Fire nem acessamos a memória de outros programas.</div>`}
function pageThemes(){return `${header('IDENTIDADE VISUAL','Temas e logos','A logo oficial acompanha a cor do tema, em todas as telas.')}<div class="grid">${themes.map(t=>`<button class="theme-tile ${state.theme===t[0]?'active':''}" data-theme="${t[0]}"><img src="assets/images/logos/logo-${t[0]}.png" alt="Logo do tema ${t[1]}"><b>${t[1]}</b><div style="height:5px;background:${t[2]};border-radius:6px;margin-top:10px"></div></button>`).join('')}</div><div class="notice" style="margin-top:14px">As logos são fornecidas no aplicativo e não podem ser substituídas pelo usuário. Tema selecionado: <strong>${themes.find(x=>x[0]===state.theme)?.[1]}</strong>.</div>`}
function pageSettings(){return `${header('PREFERÊNCIAS','Configurações','Controle animações, dados e privacidade do aplicativo.')}<div class="grid two"><div class="card"><h3>Aparência e experiência</h3><div class="kv"><span>Tema atual</span><b>${themes.find(x=>x[0]===state.theme)?.[1]}</b></div><div class="kv"><span>Ativar animações</span><input type="checkbox" id="animations" ${state.animations?'checked':''}></div><button data-nav="themes" class="secondary" style="margin-top:14px">Escolher tema</button></div><div class="card"><h3>Meus dados</h3><p>O aplicativo salva configurações no armazenamento local do Windows, no perfil do navegador usado pelo painel.</p><div class="action-row"><button class="secondary small" data-action="exportBackup">Exportar backup</button><button class="secondary small" data-action="importBackup">Importar backup</button><button class="danger small" data-action="clearData">Apagar tudo</button></div></div><div class="card"><h3>Diagnóstico</h3><p>As métricas do computador são consultadas somente quando você aciona o diagnóstico. Não solicitamos administrador.</p><button class="secondary" data-nav="optimize">Ver diagnóstico</button></div><div class="card"><h3>Tutorial e informações</h3><p>Reveja as ferramentas e encontre respostas para dúvidas frequentes.</p><button class="secondary" data-action="tutorial">Reabrir tutorial</button> <button class="danger" data-action="exitApp" style="margin-top:10px">Encerrar aplicativo</button></div></div>`}
const faqs=[['Como o gerador funciona?','Ele cruza respostas sobre emulador, mouse, estilo e dificuldades e aplica regras transparentes que resultam em seis valores iniciais na escala de 0 a 200. Você pode corrigir manualmente depois.'],['A Hype Sensi modifica o Free Fire?','Não. O aplicativo não lê nem escreve arquivos, memória ou configurações do jogo. Você copia as recomendações e aplica manualmente.'],['O editor cria códigos oficiais de HUD?','Não. Ele cria representações visuais editáveis dentro da Hype Sensi. Códigos do Free Fire somente são disponibilizados quando publicados no próprio jogo por seus usuários.'],['As sensis dos famosos são atuais?','Cada perfil diferencia configurações publicadas por terceiros das que ainda não possuem fonte. Não tratamos códigos ou valores antigos como automaticamente válidos.'],['Consigo ver a temperatura exata da CPU?','Nem sempre. Algumas máquinas oferecem sensores ACPI, mas eles não representam necessariamente a CPU. Se não houver sensor adequado, aparece apenas estimativa de carga térmica, sem números em °C.'],['É preciso permitir acesso de administrador?','Não. O aplicativo não exige privilégios administrativos. As consultas de diagnóstico usam interfaces disponíveis ao usuário atual.'],['Onde ficam meus HUDs?','No armazenamento local do aplicativo. Você pode exportar e restaurar um arquivo de backup em Configurações.'],['O Free Fire funciona automaticamente com a minha sensi?','Não existe garantia de resultado perfeito: use as recomendações como ponto de partida e calibre após testar no jogo.']];
function pageFAQ(){return `${header('CENTRAL DE AJUDA','Perguntas frequentes','Respostas sobre configurações, importação e medições do PC.')}<div class="card">${faqs.map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function pageTerms(){return `${header('LEGAL','Termos de Uso','Condições de utilização da Hype Sensi Desktop.')}<div class="card"><h3>Uso independente</h3><p>Hype Sensi é uma ferramenta independente, não afiliada ou endossada pela Garena. O aplicativo fornece recomendações, organização de sensibilidades e representação de HUDs. Não garante melhores resultados em partidas nem altera o jogo.</p><h3>Dados de terceiros</h3><p>Valores e códigos publicados por terceiros são identificados como tal. A disponibilidade, validade e atualização dessas informações podem mudar.</p><h3>Armazenamento e backups</h3><p>As alterações são mantidas localmente no dispositivo. Recomendamos fazer backups antes de remover o app ou limpar os dados do navegador. Dados apagados sem backup podem ser irrecuperáveis.</p><h3>Uso responsável</h3><p>Respeite as regras do jogo e os direitos de autoria relativos a imagens e conteúdos de terceiros. Não há acesso automatizado a contas ou dados privados.</p><div class="notice">Texto-base do aplicativo. Uma versão comercial deve complementar termos de venda, suporte, reembolso e contato oficial conforme as regras aplicáveis.</div></div>`}
function pagePrivacy(){return `${header('LEGAL','Privacidade','Dados locais e permissões transparentes.')}<div class="card"><h3>Dados armazenados</h3><p>HUDs, sensibilidades, temas e favoritos permanecem localmente no perfil de armazenamento usado pelo aplicativo. Não há conta ou banco de dados remoto.</p><h3>Informações do computador</h3><p>O diagnóstico consulta informações básicas do Windows sob demanda. O resultado aparece na tela e não é enviado a um servidor pela Hype Sensi.</p><h3>Permissões</h3><p>Não solicitamos acesso a câmera, microfone, localização, contatos nem privilégios administrativos. Abertura de links de referência pode acessar sites externos com suas próprias práticas de privacidade.</p><h3>Seus controles</h3><p>Você pode exportar, importar e apagar as configurações locais. Um backup exportado fica sob seu controle.</p><div class="notice">Descrição das funcionalidades desta versão desktop; revise antes de comercializar e divulgar dados de contato do responsável.</div></div>`}
const pages={home:pageHome,dashboard:pageDashboard,sensi:pageSensi,hud:renderHUD,hudEditor:pageHudEditor,famous:pageFamous,calibration:renderCalibration,optimize:pageOptimize,saved:pageSaved,themes:pageThemes,settings:pageSettings,faq:pageFAQ,terms:pageTerms,privacy:pagePrivacy};
function wire(){/* central delegation and selective input events are registered once */}
function modal(title,message,confirm,onConfirm){$('#overlay').classList.remove('hidden');let div=document.createElement('div');div.className='modal-wrap';div.innerHTML=`<div class="modal"><h2>${escapeHTML(title)}</h2><p class="muted">${escapeHTML(message)}</p><div class="action-row" style="justify-content:flex-end"><button class="secondary" id="modalCancel">Cancelar</button><button class="${confirm==='Excluir'?'danger':'primary'}" id="modalConfirm">${escapeHTML(confirm)}</button></div></div>`;document.body.appendChild(div);const close=()=>{div.remove();$('#overlay').classList.add('hidden')};$('#modalCancel').onclick=close;$('#modalConfirm').onclick=()=>{close();onConfirm()};div.addEventListener('click',e=>{if(e.target===div)close()})}
function formatSensi(v){return keys.map((k,i)=>`${names[i]}: ${v[k]}`).join('\n')}
function copy(text){navigator.clipboard?.writeText(text).then(()=>toast('Copiado')).catch(()=>fallbackCopy(text))||fallbackCopy(text)}
function fallbackCopy(text){let a=document.createElement('textarea');a.value=text;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove();toast('Copiado')}
function saveGenerated(){if(!generated)return;let name=prompt('Nome desta sensibilidade:','Sensi Hype '+new Date().toLocaleDateString('pt-BR'));if(name===null)return;name=name.trim()||'Minha Sensi';state.sensis.unshift({id:uid(),name,platform:'Windows / Emulador',values:structuredClone(generated),answers:structuredClone(quizAnswers),created:new Date().toISOString()});persist();toast('Sensibilidade salva em Meus Perfis')}
function download(name,data,type){let blob=new Blob([data],{type:type||'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function backup(){const data={app:'Hype Sensi WebApp',format:1,savedAt:new Date().toISOString(),sensis:state.sensis,huds:state.huds,favPlayers:state.favPlayers,theme:state.theme};download('HypeSensi-backup.json',JSON.stringify(data,null,2));toast('Backup exportado')}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let txt=await input.files[0].text(),data=JSON.parse(txt);if(data.app!=='Hype Sensi WebApp'||data.format!==1||!Array.isArray(data.sensis)||!Array.isArray(data.huds))throw Error('Arquivo não compatível');modal('Restaurar backup','Isso substituirá todas as sensibilidades e HUDs salvos neste computador. Deseja continuar?','Restaurar',()=>{state.sensis=data.sensis.filter(x=>x&&typeof x.name==='string'&&x.values&&keys.every(k=>Number.isInteger(x.values[k])&&x.values[k]>=0&&x.values[k]<=200)).slice(0,500);state.huds=data.huds.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.controls)).slice(0,500).map(x=>({...x,controls:x.controls.filter(c=>c&&typeof c.id==='string'&&typeof c.label==='string'&&Number.isFinite(c.x)&&Number.isFinite(c.y)).slice(0,100)}));state.favPlayers=Array.isArray(data.favPlayers)?data.favPlayers.filter(x=>typeof x==='string').slice(0,500):[];if(themes.some(t=>t[0]===data.theme))state.theme=data.theme;persist();applyTheme();navigate('saved');toast('Backup restaurado')})}catch(e){toast('Falha ao importar: '+e.message)}};input.click()}
async function diagnose(){let dest=$('#diagnostic');dest.innerHTML='<div class="notice">Consultando Windows sob demanda...</div>';try{let response=await fetch('api/diagnostics',{cache:'no-store'});if(!response.ok)throw Error('Falha ao consultar o sistema');let d=await response.json();let mem=d.totalRAMGB!=null?d.totalRAMGB.toFixed(1)+' GB':'Indisponível';let temp=d.acpiCelsius!=null?d.acpiCelsius.toFixed(1)+' °C (ACPI)':'Não disponível';let usage=d.cpuPercent==null?'Não disponível':d.cpuPercent+'%';dest.innerHTML=`${stat(escapeHTML(d.cpuCores||'—'),'Processadores lógicos','cpu')}${stat(mem,'Memória RAM instalada','dashboard')}${stat(usage,'Uso aproximado de CPU','activity')}${stat(temp,'Sensor térmico acessível','thermo')}${stat(d.heatLoad||'Indisponível','Carga térmica estimada','activity')}${stat(escapeHTML(d.os||'Windows'),'Sistema operacional','monitor')}`;toast('Consulta concluída')}catch(e){dest.innerHTML='<div class="notice">Não foi possível consultar as métricas do Windows nesta execução.</div>';toast('Diagnóstico indisponível')}}
// Global event delegation

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let ds=b.dataset;if(ds.nav){navigate(ds.nav);return}if(ds.theme){state.theme=ds.theme;persist();applyTheme();navigate('themes');toast('Tema atualizado');return}if(ds.answer){quizAnswers[questions[quizStep].id]=ds.answer;navigate('sensi');return}if(ds.createhud){editorHud=makeHud(Number(ds.createhud));editorSelected=editorHud.controls[0].id;editorUndo=[];editorRedo=[];navigate('hudEditor');return}if(ds.selecthud){editorSelected=ds.selecthud;navigate('hudEditor');return}if(ds.openHud){editorHud=structuredClone(state.huds.find(x=>x.id===ds.openHud));editorSelected=editorHud.controls[0]?.id||'';editorUndo=[];editorRedo=[];navigate('hudEditor');return}if(ds.duplicateHud){let h=structuredClone(state.huds.find(x=>x.id===ds.duplicateHud));if(h){h.id=uid();h.name+=' (cópia)';state.huds.unshift(h);persist();navigate('saved');toast('HUD duplicado')}return}if(ds.deleteHud){let h=state.huds.find(x=>x.id===ds.deleteHud);if(h)modal('Excluir HUD',`Confirma a exclusão de "${h.name}"? A operação não poderá ser desfeita.`,'Excluir',()=>{state.huds=state.huds.filter(x=>x.id!==h.id);persist();navigate('saved');toast('HUD excluído')});return}if(ds.openSensi){let s=state.sensis.find(x=>x.id===ds.openSensi);if(s){generated=structuredClone(s.values);quizAnswers=structuredClone(s.answers||{});navigate('sensi')}return}if(ds.duplicateSensi){let s=structuredClone(state.sensis.find(x=>x.id===ds.duplicateSensi));if(s){s.id=uid();s.name+=' (cópia)';state.sensis.unshift(s);persist();navigate('saved');toast('Sensi duplicada')}return}if(ds.deleteSensi){let s=state.sensis.find(x=>x.id===ds.deleteSensi);if(s)modal('Excluir sensibilidade',`Confirma a exclusão de "${s.name}"? Essa ação é permanente.`,'Excluir',()=>{state.sensis=state.sensis.filter(x=>x.id!==s.id);persist();navigate('saved');toast('Sensi excluída')});return}if(ds.famous){famousSelected=ds.famous;navigate('famous');return}if(ds.fav){const name=ds.fav;if(state.favPlayers.includes(name))state.favPlayers=state.favPlayers.filter(x=>x!==name);else state.favPlayers.push(name);persist();navigate('famous');return}if(ds.caldelta){let range=$('#calRange');if(range){range.value=clamp(Number(range.value)+Number(ds.caldelta),0,200);$('#calValue').textContent=range.value}return}if(ds.action){const a=ds.action;if(a==='quizPrev'){quizStep=Math.max(0,quizStep-1);navigate('sensi')}if(a==='quizNext'){if(!quizAnswers[questions[quizStep].id])return;if(quizStep<questions.length-1){quizStep++;navigate('sensi')}else{generated=generator(quizAnswers);navigate('sensi');toast('Sensi inicial gerada')}}if(a==='resetQuiz'){generated=null;quizStep=0;quizAnswers={};navigate('sensi')}if(a==='saveGenerated')saveGenerated();if(a==='copyGenerated'&&generated)copy(formatSensi(generated));if(a==='saveHud')saveHud();if(a==='resetHud'&&editorHud)modal('Restaurar HUD','Todas as posições, tamanhos e opacidades deste layout serão restaurados ao padrão.','Restaurar',()=>{editorCheckpoint();const n=editorHud.fingers;editorHud.controls=makeHud(n).controls;editorSelected=editorHud.controls[0].id;navigate('hudEditor')});if(a==='undoHud'&&editorUndo.length){editorRedo.push(JSON.stringify(editorHud.controls));editorHud.controls=JSON.parse(editorUndo.pop());navigate('hudEditor')}if(a==='redoHud'&&editorRedo.length){editorUndo.push(JSON.stringify(editorHud.controls));editorHud.controls=JSON.parse(editorRedo.pop());navigate('hudEditor')}if(a==='famousBack'){famousSelected=null;navigate('famous')}if(a==='copyFreitas')copy(formatSensi(freitas.values));if(a==='copyFreitasCode')copy(freitas.code);if(a==='exportBackup')backup();if(a==='importBackup')importBackup();if(a==='diagnose')diagnose();if(a==='exitApp')modal('Fechar aplicativo','Use o botão X no canto superior direito da janela do Windows para encerrar. Seus dados locais continuarão salvos.','Entendi',()=>{});if(a==='clearData')modal('Apagar todos os dados','Isso apagará sensibilidades, HUDs, favoritos e preferências salvos neste computador. Faça um backup antes de continuar.','Excluir',()=>{state={...defaults,sensis:[],huds:[],favPlayers:[],quiz:{}};persist();applyTheme();navigate('home');toast('Dados locais apagados')});if(a==='tutorial')modal('Tutorial Hype Sensi','Use o Painel para escolher ferramentas. Gere uma sensibilidade, calibre após testar, crie HUDs no editor e salve tudo em Meus Perfis. Em Configurações você pode exportar backups.','Entendi',()=>toast('Tutorial concluído'));if(a==='calSave'){let id=$('#calProfile')?.value,key=$('#calKey')?.value,v=Number($('#calRange')?.value);let s=state.sensis.find(x=>x.id===id);if(s&&keys.includes(key)&&Number.isFinite(v)){s.values[key]=clamp(Math.round(v),0,200);persist();toast('Ajuste salvo')}}}});
document.addEventListener('input',e=>{let t=e.target;if(t.dataset.sensirange){generated[t.dataset.sensirange]=Number(t.value);$('#sv-'+t.dataset.sensirange).textContent=t.value}if(t.id==='famousSearch'){famousSearch=t.value;updateFamousList()}if(t.id==='calRange')$('#calValue').textContent=t.value;if(t.id==='hudSize'||t.id==='hudOpacity'){let c=editorHud?.controls.find(x=>x.id===editorSelected);if(c){let k=t.id==='hudSize'?'size':'opacity';editorCheckpoint();c[k]=Number(t.value);updateHudLive()}}if(t.id==='hudX'||t.id==='hudY'){let c=editorHud?.controls.find(x=>x.id===editorSelected);if(c){let k=t.id==='hudX'?'x':'y';editorCheckpoint();c[k]=clamp(Number(t.value),0,100);updateHudLive()}}});
function updateFamousList(){let box=$('#famousList');if(!box)return;let arr=famous.filter(p=>(famousRegion==='all'||p[1]===famousRegion)&&(!favFilter||state.favPlayers.includes(p[0]))&&p[0].toLowerCase().includes(famousSearch.toLowerCase()));box.innerHTML=`<div class="row space" style="margin:17px 0"><b>${arr.length} resultado(s)</b><span class="muted">Brasil e internacional</span></div>${arr.map(famousItem).join('')||'<div class="empty">Nenhum jogador corresponde aos filtros.</div>'}`}
document.addEventListener('change',e=>{let t=e.target;if(t.id==='famousRegion'){famousRegion=t.value;updateFamousList()}if(t.id==='famousFavorites'){favFilter=t.checked;updateFamousList()}if(t.id==='animations'){state.animations=t.checked;persist();document.documentElement.classList.toggle('noanimation',!t.checked)}if(t.id==='calKey'){calibrationKey=t.value;navigate('calibration')}if(t.id==='calProfile'){selectedSensiId=t.value;navigate('calibration')}if(t.id==='controlSelect'){editorSelected=t.value;navigate('hudEditor')}if(t.id==='hudVisible'){editorChange(editorSelected,'visible',t.checked)}});
let drag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.hud-control');if(!el||!editorHud)return;let box=$('#hudCanvas');if(!box)return;editorSelected=el.dataset.control;editorCheckpoint();drag={id:el.dataset.control,rect:box.getBoundingClientRect()};el.setPointerCapture?.(e.pointerId);$$('.hud-control').forEach(x=>x.classList.toggle('selected',x===el));},true);
document.addEventListener('pointermove',e=>{if(!drag||!editorHud)return;let c=editorHud.controls.find(x=>x.id===drag.id);if(!c)return;c.x=Math.round(clamp((e.clientX-drag.rect.left)/drag.rect.width*100,0,100)*10)/10;c.y=Math.round(clamp((e.clientY-drag.rect.top)/drag.rect.height*100,0,100)*10)/10;const el=$(`[data-control="${c.id}"]`);if(el){el.style.left=c.x+'%';el.style.top=c.y+'%'}});
document.addEventListener('pointerup',()=>{if(drag){drag=null;let h=editorHud;let oldName=$('#hudName')?.value;navigate('hudEditor');if(h&&oldName)$('#hudName').value=oldName}});
$('#btnSettings').onclick=()=>navigate('settings');$('#themeShortcut').onclick=()=>navigate('themes');
applyTheme();navigate('home');if(!state.animations)document.documentElement.classList.add('noanimation');setTimeout(()=>{let s=$('#splash');s.style.opacity='0';setTimeout(()=>s.remove(),400)},2000);
